//! The bar an investment has to clear, which is usually your own credit card.
//!
//! Paying down debt at 24% is a **guaranteed, tax-free 24% return**. Nothing in a market is
//! guaranteed and nothing in a taxable account is tax-free, so the two are not comparable at face
//! value — the market has to clear a HIGHER number to be the better use of the same dollar, and this
//! module computes that number.
//!
//! # Why this exists at all
//!
//! `payoff` knows what debt costs. `evaluate` knows what a signal returns after costs. Nothing put
//! them side by side, so the decision that comes before every investing decision was the one the
//! system could not answer. A tool built to sell investing features would not ship this, because its
//! most common honest answer is **do not invest yet**.
//!
//! # What it will not do
//!
//! It does not predict market returns. The expected return is an INPUT you supply and defend, and it
//! is refused rather than defaulted — inventing it would fabricate the entire comparison. In
//! particular, do NOT feed it a backtested figure from `evaluate`: those are selected from many
//! trials, and `simulate::multiple_testing` demonstrates that the best of 200 worthless signals on
//! pure noise showed +45.9% at t=2.36. A number chosen because it looked good is not an expectation.
use crate::jurisdiction::apply_bps;
use crate::money::{money, Money};

/// One debt, as this module needs it.
#[derive(Debug, Clone, PartialEq)]
pub struct Debt {
    pub account: String,
    /// What is owed, as a POSITIVE magnitude.
    pub balance: Money,
    /// `None` means nobody recorded the rate. It does NOT mean zero — see [`Verdict::RateUnknown`].
    pub apr_bps: Option<i64>,
    /// Whether the interest is deductible (a mortgage, a qualifying student loan). Changes the
    /// answer more than people expect; see [`required_return`].
    pub deductible: bool,
}

/// What you think the market will do, and what it will cost you in tax. Every field is supplied by
/// the caller, because every one of them changes the verdict.
#[derive(Debug, Clone, PartialEq)]
pub struct Expectation {
    /// Your estimate of the ANNUAL pre-tax return, in basis points. Never defaulted.
    pub annual_return_bps: i64,
    /// The rate gains would be taxed at.
    pub tax_bps: i64,
    /// How much MORE than the guaranteed rate you demand before accepting uncertainty. Zero is
    /// permitted and is reported, because zero asserts that a certain return and an uncertain one of
    /// the same size are equally good — which is false.
    pub risk_premium_bps: i64,
    /// Where the estimate came from. A number with no provenance is a guess wearing a decimal point.
    pub source: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Verdict {
    /// The debt wins. `margin_bps` is how far short the market falls.
    PayTheDebt { margin_bps: i64 },
    /// The market clears the bar by `margin_bps`, including the risk premium.
    InvestingClears { margin_bps: i64 },
    /// ABSENT IS NOT ZERO. A missing rate must never read as 0%, because 0% makes investing win by
    /// default on a debt that might be costing 29%.
    RateUnknown,
}

impl Verdict {
    pub fn label(&self) -> &'static str {
        match self {
            Verdict::PayTheDebt { .. } => "pay the debt",
            Verdict::InvestingClears { .. } => "investing clears",
            Verdict::RateUnknown => "rate unknown",
        }
    }
}

/// The pre-tax market return needed to match paying down this debt.
///
/// # The gross-up, and why deductible debt cancels
///
/// Paying non-deductible debt saves you the full rate, TAX-FREE. Matching that with a taxable
/// investment needs `apr / (1 - tax)` — at 24% and a 25% rate, **32%**. That gap is the single most
/// missed fact in this comparison.
///
/// Deductible debt is different and the arithmetic is pleasing: you only really save
/// `apr × (1 - tax)`, because paying it off costs you the deduction. Grossing THAT back up gives
/// `apr × (1 - tax) / (1 - tax)` — the terms cancel, and the required return is simply the nominal
/// APR. So a 6% deductible mortgage needs a 6% market return, while a 6% credit card needs 8%.
///
/// Rounds UP, which makes the market's job harder. That is the conservative direction: the thing
/// being protected is the certain outcome.
pub fn required_return(apr_bps: i64, tax_bps: i64, deductible: bool) -> Result<i64, String> {
    if !(0..10_000).contains(&tax_bps) {
        return Err(format!(
            "a tax rate of {}.{:02}% is not usable here — at 100% there is no after-tax return to compare against, and a negative rate is not a thing",
            tax_bps / 100,
            (tax_bps % 100).abs()
        ));
    }
    if apr_bps < 0 {
        return Err("a negative APR is not a debt this can reason about".to_string());
    }
    if deductible {
        // The gross-up and the lost deduction cancel exactly.
        return Ok(apr_bps);
    }
    let num = i128::from(apr_bps) * 10_000;
    let den = i128::from(10_000 - tax_bps);
    // Ceiling division by hand — `div_ceil` on i128 is not stable on this toolchain, and both
    // operands are known positive here (the guards above), so the +den-1 form is exact.
    let up = (num + den - 1) / den;
    i64::try_from(up).map_err(|_| "the required return overflowed — check the inputs".to_string())
}

#[derive(Debug, Clone, PartialEq)]
pub struct Hurdle {
    pub account: String,
    pub balance: Money,
    pub apr_bps: Option<i64>,
    /// What the market must return, pre-tax, to match paying this down.
    pub required_bps: Option<i64>,
    /// The bar including your risk premium. This is what the expectation is actually judged against.
    pub bar_bps: Option<i64>,
    /// What this debt costs you over a year if you do nothing.
    pub annual_cost: Option<Money>,
    pub verdict: Verdict,
}

/// Judge one debt against an expectation.
pub fn compare(debt: &Debt, e: &Expectation) -> Result<Hurdle, String> {
    let Some(apr) = debt.apr_bps else {
        return Ok(Hurdle {
            account: debt.account.clone(),
            balance: debt.balance,
            apr_bps: None,
            required_bps: None,
            bar_bps: None,
            annual_cost: None,
            verdict: Verdict::RateUnknown,
        });
    };
    let required = required_return(apr, e.tax_bps, debt.deductible)?;
    let bar = required.saturating_add(e.risk_premium_bps.max(0));
    // A TIE GOES TO THE DEBT. Equal numbers are not an equal choice: one is certain and one is not,
    // so `>` rather than `>=` is the whole difference between an honest comparison and a flattering
    // one.
    let verdict = if e.annual_return_bps > bar {
        Verdict::InvestingClears { margin_bps: e.annual_return_bps - bar }
    } else {
        Verdict::PayTheDebt { margin_bps: bar - e.annual_return_bps }
    };
    Ok(Hurdle {
        account: debt.account.clone(),
        balance: debt.balance,
        apr_bps: Some(apr),
        required_bps: Some(required),
        bar_bps: Some(bar),
        annual_cost: Some(apply_bps(debt.balance, apr)),
        verdict,
    })
}

/// Every debt, worst first — the one costing you most against the bar leads.
///
/// Debts with an unknown rate sort to the TOP, not the bottom: an unanswered question about a
/// balance you owe is more urgent than an answered one, and putting them last is how they stay
/// unanswered.
pub fn ladder(debts: &[Debt], e: &Expectation) -> Result<Vec<Hurdle>, String> {
    let mut out: Vec<Hurdle> = debts.iter().map(|d| compare(d, e)).collect::<Result<_, _>>()?;
    out.sort_by_key(|h| match h.verdict {
        Verdict::RateUnknown => (0, 0),
        Verdict::PayTheDebt { margin_bps } => (1, -margin_bps),
        Verdict::InvestingClears { margin_bps } => (2, -margin_bps),
    });
    Ok(out)
}

/// The precondition that comes before either choice.
#[derive(Debug, Clone, PartialEq)]
pub struct Buffer {
    pub liquid: Money,
    pub monthly_need: Money,
    /// Tenths of a month, so the figure is exact without a float.
    pub months_held_tenths: i64,
    pub target_months: i64,
    pub shortfall: Money,
    pub met: bool,
}

/// Whether there is enough cash to absorb a surprise.
///
/// THIS OUTRANKS THE RATE COMPARISON, and the reason is mechanical rather than moral: with no
/// buffer, the next unavoidable expense goes back onto the same card at the same APR. You paid it
/// down and borrowed it again, so the round trip returned nothing and cost you the time. The same
/// applies to selling an investment at whatever price the market happens to be offering that week.
pub fn buffer(liquid: Money, monthly_need: Money, target_months: i64) -> Result<Buffer, String> {
    if monthly_need.minor <= 0 {
        return Err(
            "monthly need must be a positive amount — without it there is no way to say how many months of cover you hold, and a buffer measured in months is the only form of it that means anything"
                .to_string(),
        );
    }
    if target_months < 0 {
        return Err("a negative buffer target is not a target".to_string());
    }
    let months_held_tenths = liquid.minor.max(0).saturating_mul(10) / monthly_need.minor;
    let target = monthly_need.minor.saturating_mul(target_months);
    let shortfall = (target - liquid.minor).max(0);
    Ok(Buffer {
        liquid,
        monthly_need,
        months_held_tenths,
        target_months,
        shortfall: money(shortfall, liquid.currency),
        met: shortfall == 0,
    })
}

/// What to do with the next spare dollar.
#[derive(Debug, Clone, PartialEq)]
pub enum NextDollar {
    /// Build the buffer first, whatever the rates say.
    BuildBuffer { shortfall: Money },
    /// Answer the unknown rates before deciding anything.
    FindOutTheRate { accounts: Vec<String> },
    PayDebt { account: String, apr_bps: i64 },
    /// Nothing is beating the market on your own numbers.
    Invest,
    /// No debts, no buffer gap — the comparison has nothing to weigh.
    NothingToWeigh,
}

/// The single recommendation, in the order the reasons actually bind.
pub fn next_dollar(b: &Buffer, ladder: &[Hurdle]) -> NextDollar {
    if !b.met {
        return NextDollar::BuildBuffer { shortfall: b.shortfall };
    }
    let unknown: Vec<String> = ladder.iter().filter(|h| h.verdict == Verdict::RateUnknown).map(|h| h.account.clone()).collect();
    if !unknown.is_empty() {
        return NextDollar::FindOutTheRate { accounts: unknown };
    }
    for h in ladder {
        if let (Verdict::PayTheDebt { .. }, Some(apr)) = (&h.verdict, h.apr_bps) {
            return NextDollar::PayDebt { account: h.account.clone(), apr_bps: apr };
        }
    }
    if ladder.is_empty() {
        NextDollar::NothingToWeigh
    } else {
        NextDollar::Invest
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    fn card(apr: i64) -> Debt {
        Debt { account: "card".into(), balance: usd(500_000), apr_bps: Some(apr), deductible: false }
    }

    fn expect(ret: i64, tax: i64, premium: i64) -> Expectation {
        Expectation { annual_return_bps: ret, tax_bps: tax, risk_premium_bps: premium, source: "test".into() }
    }

    #[test]
    fn the_tax_gross_up_raises_the_bar_and_it_is_the_fact_people_miss() {
        // 24% non-deductible, taxed at 25%: the market must return 32% PRE-TAX to match.
        assert_eq!(required_return(2400, 2500, false).expect("valid"), 3200);
        // Same debt, no tax at all: the bar is the rate itself.
        assert_eq!(required_return(2400, 0, false).expect("valid"), 2400);
        // A higher tax rate makes the debt look BETTER, not worse.
        assert!(required_return(2400, 3700, false).expect("valid") > 3200);
        // It rounds UP, so the market is never given the benefit of a fraction.
        assert_eq!(required_return(1, 3300, false).expect("valid"), 2, "1bp / 0.67 = 1.49 → 2");
    }

    #[test]
    fn deductible_debt_cancels_exactly_and_needs_only_its_nominal_rate() {
        // The gross-up and the lost deduction are the same factor, so they cancel.
        for tax in [0, 1200, 2500, 3700] {
            assert_eq!(required_return(600, tax, true).expect("valid"), 600, "at tax {tax}");
        }
        // Which is why a 6% mortgage and a 6% card are NOT the same decision.
        assert_eq!(required_return(600, 2500, true).expect("valid"), 600);
        assert_eq!(required_return(600, 2500, false).expect("valid"), 800);
    }

    #[test]
    fn a_missing_apr_is_unknown_and_never_reads_as_zero_percent() {
        // THE DANGEROUS DEFAULT. A 0% reading makes investing win against a debt that might be
        // costing 29%, and it would do so silently.
        let d = Debt { account: "store card".into(), balance: usd(300_000), apr_bps: None, deductible: false };
        let h = compare(&d, &expect(700, 2500, 0)).expect("resolvable");
        assert_eq!(h.verdict, Verdict::RateUnknown);
        assert_eq!(h.required_bps, None);
        assert_eq!(h.annual_cost, None, "a cost computed from an unknown rate would be fiction");
        // And it is not quietly treated as clearing the bar.
        assert!(!matches!(h.verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn a_tie_goes_to_the_debt_because_certain_and_uncertain_are_not_equal() {
        // Bar is exactly 32%; an expectation of exactly 32% does NOT clear it.
        let h = compare(&card(2400), &expect(3200, 2500, 0)).expect("valid");
        assert_eq!(h.bar_bps, Some(3200));
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 0 }, "equal numbers are not an equal choice");
        // One basis point more and it clears.
        let over = compare(&card(2400), &expect(3201, 2500, 0)).expect("valid");
        assert_eq!(over.verdict, Verdict::InvestingClears { margin_bps: 1 });
    }

    #[test]
    fn the_risk_premium_raises_the_bar_it_does_not_change_the_required_return() {
        let h = compare(&card(2400), &expect(3500, 2500, 500)).expect("valid");
        assert_eq!(h.required_bps, Some(3200), "the arithmetic bar is unchanged");
        assert_eq!(h.bar_bps, Some(3700), "what you actually demand is higher");
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 200 }, "35% loses to a 37% demand");
        // Without the premium the same expectation would have cleared — which is the point of it.
        assert!(matches!(compare(&card(2400), &expect(3500, 2500, 0)).expect("valid").verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn the_realistic_case_is_that_the_card_wins_by_a_lot() {
        // A 24.99% card against a defensible 7% long-run expectation.
        let h = compare(&card(2499), &expect(700, 2500, 0)).expect("valid");
        assert_eq!(h.required_bps, Some(3332), "24.99% tax-free needs 33.32% pre-tax");
        assert_eq!(h.verdict, Verdict::PayTheDebt { margin_bps: 2632 }, "the market falls 26.32 points short");
        // And the annual cost of doing nothing is stated in money, not percent.
        assert_eq!(h.annual_cost, Some(usd(124_950)), "24.99% of 5000.00");
    }

    #[test]
    fn a_low_rate_deductible_loan_is_where_investing_actually_wins() {
        let mortgage = Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true };
        let h = compare(&mortgage, &expect(700, 2500, 100)).expect("valid");
        assert_eq!(h.required_bps, Some(300));
        assert_eq!(h.bar_bps, Some(400));
        assert_eq!(h.verdict, Verdict::InvestingClears { margin_bps: 300 });
    }

    #[test]
    fn an_impossible_tax_rate_is_refused_rather_than_dividing_by_zero() {
        assert!(required_return(2400, 10_000, false).unwrap_err().contains("at 100% there is no after-tax return"));
        assert!(required_return(2400, 12_000, false).is_err());
        assert!(required_return(2400, -100, false).is_err());
        assert!(required_return(-1, 2500, false).unwrap_err().contains("negative APR"));
        // Deductible debt still refuses the same inputs rather than short-circuiting past the check.
        assert!(required_return(600, 10_000, true).is_err());
    }

    #[test]
    fn unknown_rates_sort_to_the_top_because_that_is_what_keeps_them_from_being_ignored() {
        let debts = vec![
            Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true },
            card(2499),
            Debt { account: "mystery".into(), balance: usd(100_000), apr_bps: None, deductible: false },
            Debt { account: "auto".into(), balance: usd(1_200_000), apr_bps: Some(900), deductible: false },
        ];
        let l = ladder(&debts, &expect(700, 2500, 0)).expect("valid");
        assert_eq!(l[0].account, "mystery", "an unanswered question outranks an answered one");
        assert_eq!(l[1].account, "card", "then the worst gap");
        assert_eq!(l[2].account, "auto");
        assert_eq!(l[3].account, "mortgage", "the only one investing beats comes last");
        assert!(matches!(l[3].verdict, Verdict::InvestingClears { .. }));
    }

    #[test]
    fn the_buffer_outranks_every_rate_because_without_it_the_paydown_round_trips() {
        // 1,200.00 held against a 2,000.00 month is 0.6 months.
        let b = buffer(usd(120_000), usd(200_000), 3).expect("valid");
        assert_eq!(b.months_held_tenths, 6);
        assert_eq!(b.shortfall.minor, 480_000, "3 months is 6000.00; 1200.00 is held");
        assert!(!b.met);

        // Even against a 24.99% card, the buffer comes first.
        let l = ladder(&[card(2499)], &expect(700, 2500, 0)).expect("valid");
        assert_eq!(next_dollar(&b, &l), NextDollar::BuildBuffer { shortfall: usd(480_000) });

        // Once it is met, the card wins.
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        assert!(full.met);
        assert_eq!(full.months_held_tenths, 30);
        assert_eq!(next_dollar(&full, &l), NextDollar::PayDebt { account: "card".into(), apr_bps: 2499 });
    }

    #[test]
    fn an_unknown_rate_blocks_the_recommendation_rather_than_being_skipped_over() {
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        let debts = vec![card(300), Debt { account: "mystery".into(), balance: usd(100_000), apr_bps: None, deductible: false }];
        // Even though the 3% card loses to a 7% expectation, the unknown one must be answered first.
        let l = ladder(&debts, &expect(700, 2500, 0)).expect("valid");
        assert_eq!(next_dollar(&full, &l), NextDollar::FindOutTheRate { accounts: vec!["mystery".into()] });
    }

    #[test]
    fn with_a_buffer_and_no_debt_beating_the_market_the_answer_is_invest() {
        let full = buffer(usd(600_000), usd(200_000), 3).expect("valid");
        let mortgage = Debt { account: "mortgage".into(), balance: usd(20_000_000), apr_bps: Some(300), deductible: true };
        let l = ladder(&[mortgage], &expect(700, 2500, 100)).expect("valid");
        assert_eq!(next_dollar(&full, &l), NextDollar::Invest);
        // And with nothing at all to weigh, it says so rather than recommending anything.
        assert_eq!(next_dollar(&full, &[]), NextDollar::NothingToWeigh);
    }

    #[test]
    fn a_buffer_with_no_monthly_need_is_refused_rather_than_reported_as_infinite() {
        let err = buffer(usd(600_000), usd(0), 3).unwrap_err();
        assert!(err.contains("measured in months is the only form of it that means anything"), "{err}");
        assert!(buffer(usd(600_000), usd(-1), 3).is_err());
        assert!(buffer(usd(600_000), usd(200_000), -1).is_err());
        // Holding nothing is zero months, not an error.
        assert_eq!(buffer(usd(0), usd(200_000), 3).expect("valid").months_held_tenths, 0);
    }
}
